// Corpara offline support — generated by make_sw.py
const V = '__VERSION__';
const FILES = __FILES__;
const CDN = __CDN__;
const NET_FIRST = /(\/|index\.html|info\.js|manifest\.json|\.webmanifest)$/;

self.addEventListener('install', e => {
  e.waitUntil((async () => {
    const c = await caches.open(V);
    // revalidate with the server (cheap 304 when a file is unchanged); fall back to the previous copy if offline
    const old = (await caches.keys()).filter(k => k !== V && k.startsWith('corpara-'));
    await Promise.all(FILES.concat(CDN).map(async u => {
      try {
        const r = await fetch(u, { cache: 'no-cache' });
        if (r.ok || r.type === 'opaque') await c.put(u, r);
      } catch (err) { for (const k of old) { const m = await (await caches.open(k)).match(u); if (m) { await c.put(u, m); break; } } }
    }));
    self.skipWaiting();
  })());
});

self.addEventListener('activate', e => {
  e.waitUntil((async () => {
    for (const k of await caches.keys()) if (k !== V && k.startsWith('corpara-')) await caches.delete(k);
    await self.clients.claim();
    for (const cl of await self.clients.matchAll()) cl.postMessage({ type: 'offline-ready', v: V });
  })());
});

async function netFirst(req) {
  const c = await caches.open(V);
  try {
    const r = await Promise.race([fetch(req), new Promise((_, rej) => setTimeout(() => rej('timeout'), 4000))]);
    if (r.ok) c.put(req, r.clone());
    return r;
  } catch (err) {
    return (await c.match(req, { ignoreSearch: true })) || (await c.match('index.html')) || Response.error();
  }
}
async function cacheFirst(req) {
  const c = await caches.open(V);
  const hit = await c.match(req, { ignoreSearch: true });
  if (hit) return hit;
  const r = await fetch(req);
  if (r.ok || r.type === 'opaque') c.put(req, r.clone());
  return r;
}

self.addEventListener('fetch', e => {
  const req = e.request; if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin === location.origin) {
    if (req.mode === 'navigate' || NET_FIRST.test(url.pathname)) e.respondWith(netFirst(req));
    else e.respondWith(cacheFirst(req));
  } else if (/cdn\.jsdelivr\.net|fonts\.(googleapis|gstatic)\.com/.test(url.host)) e.respondWith(cacheFirst(req));
});
